import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
// ------------------------------------------------------------------
// Font Loader
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// Schema
// ------------------------------------------------------------------


export type PromptBottleProps = Record<string, any>;

// ------------------------------------------------------------------
// Helpers
// ------------------------------------------------------------------
const makeWavePath = (
  width: number,
  height: number,
  level: number, // 0 to 1, where 1 is full
  amplitude: number,
  frequency: number,
  offset: number
) => {
  const points = [];
  const waterHeight = height * level;
  const steps = 20;
  
  // Start from bottom left
  points.push(`M 0 ${height}`);

  // Trace top wave
  for (let i = 0; i <= steps; i++) {
    const x = (width * i) / steps;
    // Calculate y based on sine wave, relative to the top of the water level
    const waveY = (height - waterHeight) + Math.sin((x / width) * frequency + offset) * amplitude;
    points.push(`L ${x} ${waveY}`);
  }

  // Close path to bottom right -> bottom left
  points.push(`L ${width} ${height}`);
  points.push("Z");
  
  return points.join(" ");
};

// ------------------------------------------------------------------
// Component
// ------------------------------------------------------------------
const PromptBottle: React.FC<PromptBottleProps> = ({
  backgroundColor = "#e0f7fa",
  transparentBackground = false,
  durationInSeconds = 8,
  bottleColor = "rgba(100, 100, 100, 0.5)",
  waterColor = "#29b6f6",
  capColor = "#555555",
  labelColor = "#ffffff",
  promptText = "HYDRATE",
  textColor = "#333333",
  fillPercentage = 70,
}) => {
  useFontLoader(["Fredoka One", "Nunito"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout constants
  // We reduce the main body width slightly to accommodate the handle visual
  const bottleWidth = width * 0.28; 
  const bottleHeight = height * 0.65;
  
  // Entrance Animation
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Idle Float
  const floatY = Math.sin(frame / 30) * 10;
  
  // Water Animation
  const waveAmplitude = 10;
  const waveFrequency = 10; // cycles across width
  const waveOffset = frame / 15;
  
  // Clamp fill percentage
  const safeFill = Math.min(100, Math.max(0, fillPercentage)) / 100;

  // Generate Wave Path (inside bottle local coords)
  // We ensure width covers the widest part of the cup
  const waterPath = makeWavePath(
    bottleWidth,
    bottleHeight,
    safeFill,
    waveAmplitude,
    waveFrequency,
    waveOffset
  );

  // Bubble Configuration
  const bubbles = useMemo(() => {
    return new Array(8).fill(true).map((_, i) => {
      const seed = i * 123.45;
      const size = interpolate(random(seed), [0, 1], [10, 25]);
      const xPos = interpolate(random(seed + 1), [0, 1], [20, bottleWidth - 20]);
      const speed = interpolate(random(seed + 2), [0, 1], [1, 3]);
      const delay = i * 15;
      return { size, xPos, speed, delay, id: i };
    });
  }, [bottleWidth]);

  // ------------------------------------------------------------------
  // GEOMETRY DEFINITIONS (STANLEY STYLE)
  // ------------------------------------------------------------------
  
  // Proportions
  const topSectionH = bottleHeight * 0.55; 
  const taperH = bottleHeight * 0.10;
  const bottomSectionH = bottleHeight - topSectionH - taperH;
  
  const topW = bottleWidth;
  const bottomW = bottleWidth * 0.76; 
  const taperOffset = (topW - bottomW) / 2;
  const cornerRadius = 16; // Rounded bottom corners

  // Construct Cup Silhouette Path
  // M = Move, L = Line, Q = Quadratic Bezier
  // 1. Start Top-Left
  // 2. Line to Top-Right
  // 3. Line down to shoulder start (Right)
  // 4. Line diagonal to bottom section start (Right)
  // 5. Line down to bottom corner start (Right)
  // 6. Curve to bottom edge
  // 7. Line to bottom corner start (Left)
  // 8. Curve to bottom section (Left)
  // 9. Line up to shoulder end (Left)
  // 10. Line diagonal to shoulder start (Left)
  // 11. Line up to Top-Left
  // 12. Close

  const bottlePathD = `
    M 0 0
    L ${topW} 0
    L ${topW} ${topSectionH}
    L ${topW - taperOffset} ${topSectionH + taperH}
    L ${topW - taperOffset} ${bottleHeight - cornerRadius}
    Q ${topW - taperOffset} ${bottleHeight} ${topW - taperOffset - cornerRadius} ${bottleHeight}
    L ${taperOffset + cornerRadius} ${bottleHeight}
    Q ${taperOffset} ${bottleHeight} ${taperOffset} ${bottleHeight - cornerRadius}
    L ${taperOffset} ${topSectionH + taperH}
    L 0 ${topSectionH}
    L 0 0
    Z
  `;

  // Handle Geometry
  // Attached to the right side of the top section
  const handleWidth = bottleWidth * 0.35;
  const handleHeight = topSectionH * 0.8;
  const handleThick = 25;
  const handleTopY = topSectionH * 0.1;
  
  // SVG path for handle (Outline style)
  // Draws a D shape on the right side
  const handlePathD = `
    M ${topW - 5} ${handleTopY}
    h ${handleWidth * 0.4}
    q ${handleWidth * 0.6} 0 ${handleWidth * 0.6} ${handleHeight * 0.3}
    v ${handleHeight * 0.4}
    q 0 ${handleHeight * 0.3} -${handleWidth * 0.6} ${handleHeight * 0.3}
    h -${handleWidth * 0.4}
  `;

  // Straw Geometry
  const strawWidth = 24;
  const strawHeight = 120;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transform: `translateY(${floatY}px) scale(${entrance})`,
        }}
      >
        {/* CONTAINER */}
        <div
          style={{
            position: "relative",
            width: bottleWidth,
            height: bottleHeight,
            // Shift slightly left visually because of the heavy handle on the right
            transform: `translateX(-${bottleWidth * 0.1}px)`
          }}
        >

          {/* 0. HANDLE (Behind cup) */}
          <svg
            width={bottleWidth + handleWidth + 20}
            height={bottleHeight}
            viewBox={`0 0 ${bottleWidth + handleWidth + 20} ${bottleHeight}`}
            style={{ 
              position: "absolute", 
              top: 0, 
              left: 0, 
              zIndex: -1,
              pointerEvents: "none"
            }}
          >
            <path
              d={handlePathD}
              fill="none"
              stroke={capColor} 
              strokeWidth={handleThick}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            {/* Handle Inner Highlight */}
            <path
              d={handlePathD}
              fill="none"
              stroke="rgba(255,255,255,0.2)"
              strokeWidth={handleThick - 10}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>

          {/* 1. STRAW (Behind/Top) */}
          <div
             style={{
               position: "absolute",
               top: -strawHeight + 20,
               left: bottleWidth / 2 - strawWidth / 2,
               width: strawWidth,
               height: strawHeight,
               backgroundColor: "rgba(255,255,255,0.5)",
               border: `3px solid ${bottleColor}`,
               borderRadius: 4,
               transform: "rotate(5deg)",
               zIndex: -1,
             }}
          />

          {/* 2. MASK DEFS */}
          <svg width={0} height={0} style={{ position: "absolute" }}>
            <defs>
              <clipPath id="bottleClip">
                <path d={bottlePathD} />
              </clipPath>
            </defs>
          </svg>

          {/* 3. CUP BODY (Clipped Content) */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              clipPath: "url(#bottleClip)",
              backgroundColor: "rgba(255,255,255,0.15)", // Frosted look
              border: `1px solid ${bottleColor}`
            }}
          >
             {/* WATER */}
            <svg
              width="100%"
              height="100%"
              viewBox={`0 0 ${bottleWidth} ${bottleHeight}`}
              style={{ position: "absolute", bottom: 0 }}
            >
              <path d={waterPath} fill={waterColor} />
            </svg>

            {/* BUBBLES */}
            {bubbles.map((b) => {
              const yStart = bottleHeight;
              const yEnd = bottleHeight * (1 - safeFill) + 20; 
              
              const cycleDuration = 100 / b.speed; 
              const progress = ((frame - b.delay) % cycleDuration) / cycleDuration;
              
              if (frame < b.delay) return null;

              const y = interpolate(progress, [0, 1], [yStart, yEnd]);
              const opacity = interpolate(progress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]);
              const wobble = Math.sin(frame / 5 + b.id) * 5;

              return (
                <div
                  key={b.id}
                  style={{
                    position: "absolute",
                    left: b.xPos + wobble,
                    top: y,
                    width: b.size,
                    height: b.size,
                    borderRadius: "50%",
                    backgroundColor: "rgba(255,255,255,0.4)",
                    opacity,
                  }}
                />
              );
            })}
            
            {/* Gloss/Reflection on Body */}
            <div 
                style={{
                    position: "absolute",
                    left: "15%",
                    top: 0,
                    width: "10%",
                    height: "100%",
                    background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.2) 50%, rgba(255,255,255,0) 100%)",
                }}
            />
          </div>

          {/* 4. CUP OUTLINE (Overlay) */}
          <svg
            width="100%"
            height="100%"
            viewBox={`0 0 ${bottleWidth} ${bottleHeight}`}
            style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          >
            <path
              d={bottlePathD}
              fill="none"
              stroke={bottleColor}
              strokeWidth="8"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            {/* Rim Highlight */}
             <path
              d={`M 0 0 L ${bottleWidth} 0`}
              fill="none"
              stroke={bottleColor}
              strokeWidth="12"
              strokeLinecap="butt"
            />
             {/* Shoulder Line Highlight */}
             <path
              d={`M 0 ${topSectionH} L ${bottleWidth} ${topSectionH}`}
              fill="none"
              stroke={bottleColor}
              strokeWidth="4"
              strokeOpacity="0.3"
            />
          </svg>

          {/* 5. LABEL (Centered on top wide part) */}
          <div
            style={{
              position: "absolute",
              top: topSectionH * 0.3,
              left: "10%",
              width: "80%",
              height: topSectionH * 0.4,
              backgroundColor: labelColor,
              borderRadius: 15,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
              transform: `rotate(${Math.sin(frame / 20) * 1}deg)`,
            }}
          >
            <h1
              style={{
                fontFamily: "Fredoka One, sans-serif",
                color: textColor,
                fontSize: 38,
                margin: 0,
                textAlign: "center",
                lineHeight: 1,
                textTransform: "uppercase",
                letterSpacing: "1px",
              }}
            >
              {promptText}
            </h1>
          </div>

          {/* 6. LID */}
          <div
            style={{
              position: "absolute",
              top: -20,
              left: -5,
              width: bottleWidth + 10,
              height: 35,
              backgroundColor: capColor,
              borderRadius: "6px",
              border: `2px solid rgba(0,0,0,0.1)`,
              boxShadow: "0 4px 0 rgba(0,0,0,0.1)",
              zIndex: 10,
            }}
          >
             {/* Lid Detail */}
             <div style={{
                 position: "absolute",
                 top: 10,
                 left: "10%",
                 width: "80%",
                 height: 4,
                 backgroundColor: "rgba(0,0,0,0.1)",
                 borderRadius: 2
             }}/>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PromptBottle;